class Solution {
    fun mostCompetitive(nums:IntArray,k:Int):IntArray{
        val stack=IntArray(k);
        var size=0;
        for(i in nums.indices){
            while(size>0&&stack[size-1]>nums[i]&&size-1+nums.size-i>=k)size--;
            if(size<k)stack[size++]=nums[i]
        };
        return stack
    }
}

code.cpp:
class Solution {
    public: vector<int> mostCompetitive(vector<int>& nums,int k){
        vector<int> stack;
        for(int i=0;i<(int)nums.size();++i){
            while(!stack.empty()&&stack.back()>nums[i]&&(int)stack.size()-1+nums.size()-i>=k)stack.pop_back();
            if((int)stack.size()<k)stack.push_back(nums[i]);
        }
        return stack;
    }
};
